using EZapi;
using Il2Cpp;
using System.Reflection;
using System.Text.Json;
var cases=new List<object>();int passed=0,failed=0;
void Test(string name,Func<bool> test){Reset();try{if(!test())throw new Exception("assertion false");passed++;cases.Add(new{name,passed=true});}catch(Exception ex){failed++;cases.Add(new{name,passed=false,error=ex.ToString()});}}
bool Throws(Action call,string code){try{call();return false;}catch(Exception ex){return ex.Message.Contains(code,StringComparison.Ordinal);}}
void Reset(){NpcStockRuntime.Stop();GameSession.OnThread=true;GameSession.Identity=new(533);GameSession.Player=new();NativeFactoryRegistry.Rows.Clear();ItemRegistry.Definitions.Clear();ItemRegistry.NotApplied.Clear();LootTables.Found=true;LootTables.Rows=new[]{new LootEntrySnapshot("iron",1)};LootRegistry.Picks=0;LootRegistry.OriginalRolls=0;LootRegistry.Throw=false;LootRegistry.Last=null;ModHook.Events=0;ModHook.Callback=null;DebugNpcStock.Running=false;StoreStation.Day=4;GameBuildFingerprint.IsKnown=true;NativeHookGroup.Live=true;NpcStockRuntime.Start();NpcStockRuntime.DirectoryReady();}
