bool Roll(out string? id)=>NpcStockApi.TryRoll("materialTable",NpcTradeStockCategory.Material,NpcTradeStockSupplier.Inventor,out id);
object? Invoke(string name,params object?[] args)=>typeof(NpcStockRuntime).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Static)!.Invoke(null,args);
long Enter(bool night=false,bool miner=false)=>(long)Invoke("Enter",NpcTradeStockSupplier.Inventor,night,miner)!;
bool Routed(out string? id){object?[] args={"materialTable","test.group","unmodified"};var original=(bool)Invoke("Roll",args)!;id=(string?)args[2];return !original;}

